#include <iostream>

template <typename Arg1, typename Arg2, typename Result>
class PointerToBinaryFunction {
public:
    Result operator()(const Arg1& a, const Arg2& b) const {
        // Example implementation: sum if numeric types
        return a + b;
    }
};

int main() {
    PointerToBinaryFunction<int, int, int> add;
    std::cout << "Sum: " << add(3, 4) << std::endl;
    return 0;
}
